SELECT id, project_id, project_task_id, execution_contract_id, acceptance_type,
       activity_status, current_report_version_id, version,
       creator, create_time, updater, update_time, deleted, tenant_id
FROM acc_acceptance
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND acceptance_type = #{query.acceptanceType}
  AND deleted = 0
FOR UPDATE
